import dataclasses
import difflib
import json
import os
import re
import sys
from pathlib import Path

# TO CONFIGURE, DO NOT EDIT THIS FILE. There are two config files:
#   finbot.env       the startup file: DATA_DIR, ip, port, credentials, the home chats. Never read by the
#                    bot: the launcher loads it into the environment (systemd EnvironmentFile=, docker --env-file,
#                    init.d `set -a; . finbot.env`). A change needs a restart.
#   preferences.conf how the bot behaves: <DATA_DIR>/preferences.conf, read by the bot itself at start and on every
#                    reload (SIGHUP).

REPO_DIR = Path(__file__).resolve().parent.parent

STARTUP_KEYS = ('DATA_DIR', 'ip', 'port', 'telegramChatID', 'scheduler_catchup', 'sharesight_code',
	'sharesight_client_id', 'sharesight_client_secret', 'slackBotToken', 'slackAppToken', 'slackChannelID',
	'slackOutgoingToken', 'slackOutgoingWebhook', 'slackSigningSecret', 'telegramBotToken', 'telegramOutgoingToken',
	'telegramOutgoingWebhook', 'discordBotToken', 'discordChannelID', 'discordOutgoingWebhook', 'discordPublicKey')
SECRET_KEYS = ('sharesight_code', 'sharesight_client_id', 'sharesight_client_secret', 'slackBotToken', 'slackAppToken',
	'slackOutgoingToken', 'slackOutgoingWebhook', 'slackSigningSecret', 'telegramBotToken', 'telegramOutgoingToken',
	'telegramOutgoingWebhook', 'discordBotToken', 'discordOutgoingWebhook') # never printed
PREFERENCES_FILE = 'preferences.conf'
RETIRED = { # keys of either file that do nothing any more: accepted, so that they never stop a start, with a note at
	# start saying what to do instead
	'alliterate': 'delete the line',
	'chunk_maxlines': 'delete the line',
	'performance_use_sharesight': 'delete the line (price performance comes from Yahoo)',
	'slack_webhook': 'the scheduled reports go to slackChannelID as the bot (slackBotToken); set those, and delete the'
		' line',
	'discord_webhook': 'the scheduled reports go to discordChannelID as the bot (discordBotToken); set those, and'
		' delete the line',
	'scheduler': 'the scheduler is always on, and a schedule without jobs runs nothing; delete the line',
}
OLD_ENV = REPO_DIR / '.env' # the single config file of old versions, which python-dotenv loaded; nothing reads it now


class ConfigError(Exception):
	"""One or more problems, each already naming the file and line. `errors` is the list."""
	def __init__(self, errors):
		"""errors: one message or a list of them."""
		self.errors = [errors] if isinstance(errors, str) else list(errors)
		super().__init__('\n'.join(self.errors))


def key_problem(key, this_keys, other_keys, other_file):
	"""Why `key` may not be in this file, or None."""
	if key in this_keys:
		return None
	if key in other_keys:
		why = ' (a change needs a restart)' if other_file == 'finbot.env' else ' (it is reloadable)'
		return f"{key} belongs in {other_file}" + why
	if key == 'volatile_multiplier':
		return 'volatile_multiplier was renamed to volatility_multiplier'
	near = difflib.get_close_matches(key, list(this_keys) + list(other_keys), n=1)
	return f'unknown key {key}' + (f' (did you mean {near[0]}?)' if near else '')


def parse_assignments(text, path, classify):
	"""KEY=value lines -> ({key: value}, [errors]). Blank and # lines are skipped, one pair of matching quotes is
	stripped, `classify(key)` returns a reason to refuse the key. Every error names the file and line."""
	values, errors = {}, []
	for number, raw in enumerate(text.splitlines(), 1):
		line = raw.strip()
		if not line or line.startswith('#'):
			continue
		where = f'{path} line {number}'
		if line.startswith('['):
			errors.append(f'{where}: no sections, one KEY=value per line')
			continue
		key, sep, value = line.partition('=')
		key = key.strip()
		if not sep or not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', key):
			errors.append(f'{where}: expected KEY=value')
			continue
		if problem := classify(key):
			errors.append(f'{where}: {problem}')
			continue
		value = value.strip()
		if len(value) >= 2 and value[0] == value[-1] and value[0] in '\'"':
			value = value[1:-1]
		if key in values:
			errors.append(f'{where}: {key} is set twice')
			continue
		values[key] = value
	return values, errors


def read_text(path):
	"""The file's text, None if it does not exist. Raises ConfigError if it cannot be read."""
	try:
		return Path(path).read_text(encoding='utf-8')
	except FileNotFoundError:
		return None
	except (OSError, UnicodeDecodeError) as e:
		raise ConfigError(f'cannot read {path}: {getattr(e, "strerror", None) or e}')


def read_preferences(path):
	"""{key: value} of a preferences.conf, None if there is none. Raises ConfigError for anything wrong with it."""
	text = read_text(path)
	if text is None:
		return None
	values, errors = parse_assignments(text, path, lambda key: None if key in RETIRED else
		key_problem(key, PREFERENCE_KEYS, STARTUP_KEYS, 'finbot.env'))
	if errors:
		raise ConfigError(errors)
	return values


def read_startup_file(path):
	"""{key: value} of a finbot.env, for checking it offline (the bot never reads this file). Raises ConfigError."""
	text = read_text(path)
	if text is None:
		raise ConfigError(f'{path} does not exist')
	values, errors = parse_assignments(text, path, lambda key: None if key in RETIRED else
		key_problem(key, STARTUP_KEYS, PREFERENCE_KEYS, PREFERENCES_FILE))
	if errors:
		raise ConfigError(errors)
	return values


TRUE_WORDS = ('true', '1', 't', 'yes', 'y', 'on')
FALSE_WORDS = ('false', '0', 'f', 'no', 'n', 'off')


class _Reader:
	"""Typed reads from a getenv(name, default); a bad value is remembered, the default used, and all problems raised
	together. A blank value means unset: the default."""
	def __init__(self, getenv):
		"""getenv(name, default) supplies the values; the problems found collect in `errors` until check()."""
		self.getenv = getenv
		self.errors = []

	def value(self, name, default):
		"""The raw value, or default when it is unset or blank."""
		value = self.getenv(name, default)
		return default if value == '' else value

	def str(self, name, default=None):
		"""A text setting."""
		return self.value(name, default)

	def blankable(self, name, default):
		"""A text setting where a blank value means none (''), not the default."""
		value = self.getenv(name, default)
		return '' if value is None else str(value).strip()

	def bool(self, name, default):
		"""A boolean: true/false, yes/no, on/off, 1/0 or t/f in any case; anything else is an error, giving default."""
		value = self.value(name, default)
		word = str(value).strip().lower()
		if word in TRUE_WORDS or word in FALSE_WORDS:
			return word in TRUE_WORDS
		self.errors.append(f"{name}={value!r} is not true or false")
		return default

	def number(self, kind, name, default):
		"""A setting of type `kind` (int or float). A value that is not one is an error, and gives default."""
		value = self.value(name, default)
		try:
			return kind(value)
		except ValueError:
			self.errors.append(f"{name}={value!r} is not a {'whole number' if kind is int else 'number'}")
			return kind(default)

	def int(self, name, default):
		"""A whole-number setting."""
		return self.number(int, name, default)

	def float(self, name, default):
		"""A number setting."""
		return self.number(float, name, default)

	def words(self, name, default):
		"""A list of words, separated by spaces: a tuple of them."""
		value = self.value(name, default)
		return tuple(value.split()) if isinstance(value, str) else tuple(value)

	def check(self):
		"""Raise ConfigError with every problem found so far."""
		if self.errors:
			raise ConfigError(self.errors)


@dataclasses.dataclass(frozen=True)
class Env:
	"""The startup settings: finbot.env, which the launcher loads into the environment; fixed for the process."""
	data_dir: str # state: each chat's jobs, the watchlist, seen trades, ratings, preferences.conf
	cache_dir: str # data_dir/cache
	ip: str
	port: int
	scheduler_catchup: int # minutes: a run missed while the bot was down still fires if it was due this recently
	telegramChatID: str # Telegram's home chat (its first jobs, the error reports); '' when unset, like the rest below
	telegramBotToken: str
	telegramOutgoingWebhook: str
	telegramOutgoingToken: str
	slackBotToken: str
	slackAppToken: str # xapp-: Socket Mode, Slack's pull mode (without slackOutgoingWebhook)
	slackChannelID: str # with slackBotToken, Slack's home chat (its first jobs, the error reports)
	slackOutgoingWebhook: str
	slackOutgoingToken: str
	slackSigningSecret: str
	discordBotToken: str
	discordChannelID: str # with discordBotToken, Discord's home chat (its first jobs, the error reports)
	discordOutgoingWebhook: str # the interactions endpoint URL (http mode); unset, finbot keeps to the gateway
	discordPublicKey: str # the app's key, which checks the signature of each interaction posted to the endpoint
	sharesight_auth: dict
	telegram_api: str # the Bot API's base URL for telegramBotToken ('' without one): a method's name follows it

	@property
	def preferences_path(self):
		"""Where preferences.conf is read from: the data dir."""
		return self.data_dir + '/' + PREFERENCES_FILE


def startup_values(getenv):
	"""The settings fixed when the bot starts (finbot.env), computed from getenv(name, default). Raises ConfigError."""
	r = _Reader(getenv)
	data_dir = getenv('DATA_DIR') or (getenv('STATE_DIRECTORY') or '').split(':')[0] or 'var'
	data_dir = str(REPO_DIR / data_dir) # a relative one is in the checkout, wherever finbot starts
	token = (getenv('telegramBotToken') or '').rstrip('/')
	env = Env(
		data_dir=data_dir,
		cache_dir=data_dir + '/cache',
		ip=r.str('ip', '127.0.0.1'),
		port=r.int('port', 5000),
		scheduler_catchup=r.int('scheduler_catchup', 5),
		telegramChatID=r.str('telegramChatID', ''),
		telegramBotToken=r.str('telegramBotToken', ''),
		telegramOutgoingWebhook=r.str('telegramOutgoingWebhook', ''),
		telegramOutgoingToken=r.str('telegramOutgoingToken', ''),
		slackBotToken=r.str('slackBotToken', ''),
		slackAppToken=r.str('slackAppToken', ''),
		slackChannelID=r.str('slackChannelID', ''),
		slackOutgoingWebhook=r.str('slackOutgoingWebhook', ''),
		slackOutgoingToken=r.str('slackOutgoingToken', ''),
		slackSigningSecret=r.str('slackSigningSecret', ''),
		discordBotToken=r.str('discordBotToken', ''),
		discordChannelID=r.str('discordChannelID', ''),
		discordOutgoingWebhook=r.str('discordOutgoingWebhook', ''),
		discordPublicKey=r.str('discordPublicKey', ''),
		sharesight_auth={
			"grant_type": 'client_credentials',
			"code": getenv('sharesight_code'),
			"client_id": getenv('sharesight_client_id'),
			"client_secret": getenv('sharesight_client_secret'),
			"redirect_uri": 'urn:ietf:wg:oauth:2.0:oob'
		},
		telegram_api=f'https://api.telegram.org/bot{token}/' if token else '')
	r.check()
	return env


@dataclasses.dataclass(frozen=True)
class Prefs:
	"""The preferences: preferences.conf, which the bot reads at start and on every reload, each with its default here
	and read as its type says (preference_values). Read them as config.prefs.<name> when they are used, never into a
	default or a module constant, so that a reload is seen."""
	cache: bool = True
	cache_seconds: int = 43200
	country_code: str = 'AU'
	debug: bool = False
	demote_leveraged: bool = True
	demote_volatile: bool = True
	exchange_suffix: str = 'AX' # Yahoo's suffix for the local exchange: a bare ticker Yahoo does not know gets it
	exclude_portfolios: tuple = () # portfolio ids
	future_days: int = 30
	graph: bool = True
	http_timeout: int = 18
	hyperlink: bool = True
	hyperlinkFooter: bool = True
	hyperlinkProvider: str = 'google'
	include_portfolios: tuple = () # portfolio ids
	min_analysts: int = 7 # .buy, .sell and .forward pe list only stocks this many analysts cover
	past_days: int = 28
	performance_cache_seconds: int = 2400 # Sharesight performance reports (40 minutes: sharesight_warm runs every 30)
	price_percent: float = 5.0
	print_headers: bool = False
	shorts_percent: int = 15
	timezone: str = 'Australia/Melbourne'
	trades_use_yahoo: bool = True # set False if Yahoo breaks
	volatility_multiplier: float = 2.0
	# the file's own lines, for job processes
	source: dict = dataclasses.field(default_factory=dict, compare=False, repr=False)


def preference_values(getenv, source=None):
	"""The preferences (preferences.conf), computed from getenv(name, default): each read as its Prefs field's type
	says (a tuple is a list of words), its default the field's. `source` is the file's own {key: value}. Raises
	ConfigError listing every bad value."""
	r = _Reader(getenv)
	readers = {bool: r.bool, int: r.int, float: r.float, str: r.str, tuple: r.words,
		'exchange_suffix': lambda name, default: r.blankable(name, default).removeprefix('.').upper(), # blank: none
		'hyperlinkProvider': lambda name, default: r.str(name, default).lower()}
	values = {field.name: readers.get(field.name, readers[field.type])(field.name, field.default)
		for field in dataclasses.fields(Prefs) if field.compare}
	r.check()
	return Prefs(**values, source=dict(source or {}))


# preferences.conf's keys: what a reload can change
PREFERENCE_KEYS = tuple(field.name for field in dataclasses.fields(Prefs) if field.compare)


def _getenv_for(preferences):
	"""getenv(name, default): preferences.conf first (preference keys only), then the process environment."""
	def getenv(name, default=None):
		"""A preference from preferences.conf, else the process environment's value, else default."""
		if name in preferences:
			return preferences[name]
		return os.environ.get(name, default)
	return getenv


def print_errors(e):
	"""Log a ConfigError's problems, a line each."""
	for line in e.errors:
		print('ERROR config:', line, file=sys.stderr)

def _fail(e):
	"""Log the configuration errors and exit: finbot does not start with a bad setting."""
	print_errors(e)
	sys.exit(1)


try:
	env = startup_values(os.environ.get)
	preferences_path = env.preferences_path
	_preferences = read_preferences(preferences_path) or {}
	prefs = preference_values(_getenv_for(_preferences), _preferences)
except ConfigError as e:
	_fail(e)

for _dir in (env.data_dir, env.cache_dir):
	# util/check_config.py, possibly run as root: must not create directories the service user then cannot write
	if os.environ.get('FINBOT_CHECK_ONLY'):
		break
	try:
		os.makedirs(_dir, exist_ok=True)
	except OSError as e: # e.g. read-only filesystem (Lambda)
		print("config: can't create", _dir, e, file=sys.stderr)

# matplotlib needs a writable config/cache dir; without a home directory (systemd DynamicUser, containers) it fails
os.environ.setdefault('MPLCONFIGDIR', os.path.abspath(env.cache_dir + '/matplotlib'))

def data_file(name):
	"""Where a data file is read from: the user's copy in the data dir if any, else the default shipped in defaults/."""
	user = env.data_dir + '/' + name
	return user if os.path.isfile(user) else str(REPO_DIR / 'defaults' / name)

_data_files = {} # path -> (modification time, parsed JSON)

def data_json(name, default=None):
	"""A data file's JSON (the user's copy or the shipped default, as data_file has it), or `default` when there is
	neither. Parsed again only when the file changes; callers must not modify what they get."""
	path = data_file(name)
	try:
		mtime = os.path.getmtime(path)
	except OSError:
		return default
	if (cached := _data_files.get(path)) and cached[0] == mtime:
		return cached[1]
	with open(path, encoding="utf-8") as f:
		value = json.load(f)
	_data_files[path] = (mtime, value)
	return value


def reload():
	"""Re-read preferences.conf and apply it: config.prefs is replaced in one assignment, so a request never sees half
	of a reload. All or nothing. Returns one line per change; raises ConfigError (nothing applied) if the file is
	missing, unreadable or invalid."""
	global prefs
	new = read_preferences(preferences_path)
	if new is None:
		raise ConfigError(f'reload requested but {preferences_path} does not exist; nothing reloaded')
	values = preference_values(_getenv_for(new), new)
	changes = [f"{name} {getattr(prefs, name)!r} -> {getattr(values, name)!r}" for name in PREFERENCE_KEYS
		if getattr(prefs, name) != getattr(values, name)]
	prefs = values
	return changes


def check_startup_environment():
	"""For bot.py at start. Preferences must come from preferences.conf, not from the environment that finbot.env fills,
	and a leftover .env from before the split stops the start: its settings would otherwise be silently ignored."""
	problems = [f'{key} is a preference; move it from finbot.env to {PREFERENCES_FILE}'
		for key in PREFERENCE_KEYS if key in os.environ]
	if 'volatile_multiplier' in os.environ: # the old name, from before the split: it never worked as a preference
		problems.append('volatile_multiplier was renamed to volatility_multiplier, a preference; move it from'
			f' finbot.env to {PREFERENCES_FILE}')
	if OLD_ENV.exists():
		problems.append(f'{OLD_ENV} is the old single config file, which finbot no longer reads; it will not start'
			' while the file is there')
		problems.append(f'split it with {REPO_DIR}/util/split_env.py, which writes finbot.env.new and'
			f' preferences.conf.new beside it; put finbot.env where your launcher loads it and {PREFERENCES_FILE} in'
			f' {env.data_dir}, then delete {OLD_ENV}')
	if problems:
		raise ConfigError(problems)


def startup_report():
	"""Lines for the log at start: where the config came from (counts only; check_config names the problems)."""
	provided = [key for key in STARTUP_KEYS if key in os.environ]
	lines = [f'startup environment provides {len(provided)} of {len(STARTUP_KEYS)} startup keys (values hidden)']
	if os.path.isfile(preferences_path):
		lines.append(f'preferences from {preferences_path} ({len(prefs.source)} set; reload with SIGHUP)')
	else:
		lines.append(f'no {PREFERENCES_FILE} in {env.data_dir}, using the defaults; reload will have nothing to'
			' re-read')
	return lines + retired_notes(os.environ, 'finbot.env') + retired_notes(prefs.source)


def retired_notes(values, file=PREFERENCES_FILE):
	"""A line for each key of a file's {key: value} that does nothing any more, saying what to do instead."""
	return [f'{key} in {file} does nothing any more: {instead}' for key, instead in RETIRED.items() if key in values]


def startup_warnings(settings=None):
	"""Settings in finbot.env (an Env; the running one by default) that do not stop the start but keep part of the bot
	from working, or do nothing, a line each."""
	s = settings or env
	warnings = []
	if s.slackBotToken and not (s.slackAppToken or s.slackOutgoingWebhook):
		warnings.append('slackBotToken is set but neither slackAppToken nor slackOutgoingWebhook is: finbot hears'
			' nothing from Slack, so its commands and buttons get no answer')
	for key in ('slackOutgoingWebhook', 'slackAppToken'):
		if getattr(s, key) and not s.slackBotToken:
			warnings.append(f'{key} is set but slackBotToken is not: Slack commands will get no reply')
	if s.slackAppToken and s.slackOutgoingWebhook:
		warnings.append('slackAppToken is set but so is slackOutgoingWebhook: Slack posts its updates there'
			' (http mode), and the app-level token is not used')
	if s.slackAppToken and not s.slackAppToken.startswith('xapp-'):
		warnings.append("slackAppToken does not start with xapp-: it must be an app-level token (the app's Basic"
			' Information, App-Level Tokens), not the bot token')
	if s.slackChannelID and not s.slackBotToken:
		warnings.append('slackChannelID is set but slackBotToken is not: scheduled reports cannot go there as the bot')
	if s.slackOutgoingWebhook and not (s.slackSigningSecret or s.slackOutgoingToken):
		warnings.append('slackOutgoingWebhook is set but neither slackSigningSecret nor slackOutgoingToken is:'
			' every Slack request will be refused')
	if s.telegramOutgoingWebhook and not s.telegramOutgoingToken:
		warnings.append('telegramOutgoingWebhook is set but telegramOutgoingToken is not: every Telegram update will be'
			' refused')
	if s.telegramOutgoingToken and not re.fullmatch(r'[A-Za-z0-9_-]{1,256}', s.telegramOutgoingToken):
		warnings.append('telegramOutgoingToken is not 1 to 256 letters, digits, _ or -: Telegram takes no other as the'
			" webhook's secret, so setting the webhook will fail")
	if s.telegramOutgoingToken and not s.telegramOutgoingWebhook:
		warnings.append('telegramOutgoingToken is set but telegramOutgoingWebhook is not: finbot fetches its Telegram'
			' updates (pull mode), and the token is not used')
	if s.discordOutgoingWebhook and not s.discordBotToken:
		warnings.append('discordOutgoingWebhook is set but discordBotToken is not: Discord commands will get no reply')
	if s.discordChannelID and not s.discordBotToken:
		warnings.append('discordChannelID is set but discordBotToken is not: scheduled reports cannot go there as the'
			' bot')
	if s.discordOutgoingWebhook and not re.fullmatch(r'[0-9a-fA-F]{64}', s.discordPublicKey):
		warnings.append("discordOutgoingWebhook is set but discordPublicKey is not the app's public key (64 hex"
			' digits): every Discord interaction will be refused')
	if s.discordPublicKey and not s.discordOutgoingWebhook:
		warnings.append('discordPublicKey is set but discordOutgoingWebhook is not: finbot keeps to the Discord gateway'
			' (pull mode), and the key is not used')
	return warnings
